-- Forward15; no old SQL, authored history or original14 manifest is rewritten.

CREATE TABLE memory_legacy_configuration (installation_id TEXT PRIMARY KEY,repository_id TEXT NOT NULL,attempt_id TEXT NOT NULL UNIQUE,request_hash TEXT NOT NULL,baseline_hash TEXT NOT NULL,target_json TEXT NOT NULL CHECK(json_valid(target_json)),pin_hash TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'maintenance' CHECK(state IN('maintenance','exposed')),revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>=1),final_id TEXT,CHECK((state='exposed')=(final_id IS NOT NULL)));

CREATE TABLE memory_legacy_attempts (id TEXT PRIMARY KEY,installation_id TEXT NOT NULL,repository_id TEXT NOT NULL,request_hash TEXT NOT NULL UNIQUE,review_hash TEXT NOT NULL,inventory_hash TEXT NOT NULL,source_version INTEGER NOT NULL CHECK(source_version IN(1,2,3,4,5,6,10,11,14)),target_json TEXT NOT NULL CHECK(json_valid(target_json)),pin_hash TEXT NOT NULL,source_json TEXT NOT NULL CHECK(json_valid(source_json)),review_json TEXT NOT NULL CHECK(json_valid(review_json)),universe_json TEXT NOT NULL CHECK(json_valid(universe_json)),universe_hash TEXT NOT NULL,source_schema_hash TEXT NOT NULL,history_hash TEXT NOT NULL,backup_hash TEXT NOT NULL,ownership_hash TEXT NOT NULL,predecessor_id TEXT,created_at INTEGER NOT NULL);

CREATE TABLE memory_legacy_baselines (installation_id TEXT PRIMARY KEY,attempt_id TEXT NOT NULL UNIQUE REFERENCES memory_legacy_attempts(id),baseline_hash TEXT NOT NULL,request_hash TEXT NOT NULL,source_version INTEGER NOT NULL,lineage TEXT NOT NULL CHECK(lineage IN('retained10','retained11','reviewed-adoption','retained14')),source_manifest_hash TEXT NOT NULL,history_hash TEXT NOT NULL,backup_hash TEXT NOT NULL,ownership_hash TEXT NOT NULL,original_json TEXT NOT NULL CHECK(json_valid(original_json)),compatibility_attempt_id TEXT,compatibility_audit_id TEXT REFERENCES memory_machine_audit(id),CHECK((source_version=14)=(compatibility_audit_id IS NULL)));

CREATE TABLE memory_legacy_manifests (attempt_id TEXT PRIMARY KEY REFERENCES memory_legacy_attempts(id),schema_version INTEGER NOT NULL CHECK(schema_version=15),manifest_hash TEXT NOT NULL,schema_hash TEXT NOT NULL,protocol_hash TEXT NOT NULL,route_contract_hash TEXT NOT NULL);

CREATE TABLE memory_legacy_closures (id TEXT PRIMARY KEY,attempt_id TEXT NOT NULL REFERENCES memory_legacy_attempts(id),inventory_hash TEXT NOT NULL,closure_hash TEXT NOT NULL,revision_hash TEXT NOT NULL,observation_id TEXT NOT NULL,observed_at INTEGER NOT NULL,evidence_json TEXT NOT NULL CHECK(json_valid(evidence_json)));

CREATE TABLE memory_legacy_retirements (attempt_id TEXT NOT NULL REFERENCES memory_legacy_attempts(id),credential_id TEXT NOT NULL,kind TEXT NOT NULL,original_scope_hash TEXT NOT NULL,readback_hash TEXT NOT NULL,permissions_hash TEXT,PRIMARY KEY(attempt_id,credential_id));

CREATE TABLE memory_legacy_pieces (attempt_id TEXT NOT NULL REFERENCES memory_legacy_attempts(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),payload_json TEXT NOT NULL CHECK(json_valid(payload_json)),payload_hash TEXT NOT NULL,PRIMARY KEY(attempt_id,ordinal));

CREATE TABLE memory_legacy_claims (id TEXT PRIMARY KEY,attempt_id TEXT NOT NULL,ordinal INTEGER NOT NULL,kind TEXT NOT NULL CHECK(kind IN('fact','session','raw')),original_id TEXT NOT NULL,snapshot_hash TEXT NOT NULL,evidence_hash TEXT NOT NULL,record_json TEXT NOT NULL CHECK(json_valid(record_json)),machine_id TEXT NOT NULL,grant_id TEXT NOT NULL,key_commitment TEXT NOT NULL,scope TEXT NOT NULL,machine_revision INTEGER NOT NULL,grant_revision INTEGER NOT NULL,credential_generation INTEGER NOT NULL,visibility TEXT NOT NULL CHECK(visibility IN('private','shared','admin-only')),UNIQUE(attempt_id,kind,original_id),FOREIGN KEY(attempt_id,ordinal) REFERENCES memory_legacy_pieces(attempt_id,ordinal));

CREATE TABLE memory_legacy_quarantine (attempt_id TEXT NOT NULL REFERENCES memory_legacy_attempts(id),kind TEXT NOT NULL CHECK(kind IN('fact','session','raw')),original_id TEXT NOT NULL,snapshot_hash TEXT NOT NULL,PRIMARY KEY(attempt_id,kind,original_id));

CREATE TABLE memory_legacy_corrections (id TEXT PRIMARY KEY,attempt_id TEXT NOT NULL REFERENCES memory_data_attempts(id),predecessor_id TEXT NOT NULL,old_fact_id INTEGER NOT NULL REFERENCES facts(id),new_fact_id INTEGER NOT NULL REFERENCES facts(id),ordinal INTEGER NOT NULL,machine_id TEXT NOT NULL,claim_id TEXT NOT NULL REFERENCES memory_legacy_claims(id),UNIQUE(attempt_id,old_fact_id));

CREATE TABLE memory_legacy_access_audit (id TEXT PRIMARY KEY,installation_id TEXT NOT NULL,machine_id TEXT NOT NULL,grant_id TEXT NOT NULL,operation TEXT NOT NULL,request_hash TEXT NOT NULL,scope_json TEXT NOT NULL CHECK(json_valid(scope_json)),created_at INTEGER NOT NULL);

CREATE TABLE memory_legacy_audit (id TEXT PRIMARY KEY,attempt_id TEXT NOT NULL UNIQUE REFERENCES memory_legacy_attempts(id),request_hash TEXT NOT NULL,closure_id TEXT NOT NULL REFERENCES memory_legacy_closures(id),outcome_json TEXT NOT NULL CHECK(json_valid(outcome_json)));

CREATE TABLE memory_legacy_completions (attempt_id TEXT PRIMARY KEY REFERENCES memory_legacy_attempts(id),request_hash TEXT NOT NULL,audit_id TEXT NOT NULL UNIQUE REFERENCES memory_legacy_audit(id),closure_id TEXT NOT NULL REFERENCES memory_legacy_closures(id),claims_hash TEXT NOT NULL,universe_hash TEXT NOT NULL,claim_count INTEGER NOT NULL,piece_count INTEGER NOT NULL,quarantine_count INTEGER NOT NULL,machine_id TEXT NOT NULL,grant_id TEXT NOT NULL,key_commitment TEXT NOT NULL,machine_revision INTEGER NOT NULL,grant_revision INTEGER NOT NULL,credential_generation INTEGER NOT NULL,scope TEXT NOT NULL,created_at INTEGER NOT NULL);

CREATE TABLE memory_legacy_protocol_transitions (id TEXT PRIMARY KEY,attempt_id TEXT NOT NULL UNIQUE REFERENCES memory_legacy_attempts(id),predecessor_activation_id TEXT NOT NULL REFERENCES memory_runtime_activations(attempt_id),predecessor_hash TEXT NOT NULL,protocol_hash TEXT NOT NULL,route_contract_hash TEXT NOT NULL,source_hash TEXT NOT NULL,pin_hash TEXT NOT NULL);

CREATE TABLE memory_legacy_deployments (id TEXT PRIMARY KEY,attempt_id TEXT NOT NULL REFERENCES memory_legacy_attempts(id),predecessor_id TEXT NOT NULL UNIQUE,previous_pin_hash TEXT NOT NULL,pin_hash TEXT NOT NULL,source_hash TEXT NOT NULL,evidence_json TEXT NOT NULL CHECK(json_valid(evidence_json)),review_hash TEXT NOT NULL,protocol_hash TEXT NOT NULL,route_contract_hash TEXT NOT NULL,rollback INTEGER NOT NULL CHECK(rollback IN(0,1)));

CREATE TABLE memory_legacy_ownership_corrections (id TEXT PRIMARY KEY,predecessor_id TEXT NOT NULL UNIQUE,claim_id TEXT NOT NULL REFERENCES memory_legacy_claims(id),request_hash TEXT NOT NULL,evidence_json TEXT NOT NULL CHECK(json_valid(evidence_json)),destination_json TEXT NOT NULL CHECK(json_valid(destination_json)),visibility TEXT NOT NULL CHECK(visibility IN('private','shared','admin-only')),record_hash TEXT NOT NULL,created_at INTEGER NOT NULL);

CREATE TABLE memory_legacy_ownership_completions (correction_id TEXT PRIMARY KEY REFERENCES memory_legacy_ownership_corrections(id),request_hash TEXT NOT NULL,audit_hash TEXT NOT NULL,created_at INTEGER NOT NULL);

CREATE TABLE memory_legacy_deployment_attempts (id TEXT PRIMARY KEY,installation_id TEXT NOT NULL,request_hash TEXT NOT NULL,expected_json TEXT NOT NULL CHECK(json_valid(expected_json)),payload_json TEXT NOT NULL CHECK(json_valid(payload_json)),source_hash TEXT NOT NULL,created_at INTEGER NOT NULL);

CREATE TABLE memory_legacy_deployment_audit (id TEXT PRIMARY KEY,attempt_id TEXT NOT NULL UNIQUE REFERENCES memory_legacy_deployment_attempts(id),request_hash TEXT NOT NULL,outcome_json TEXT NOT NULL CHECK(json_valid(outcome_json)));

CREATE TABLE memory_legacy_deployment_completions (attempt_id TEXT PRIMARY KEY REFERENCES memory_legacy_deployment_attempts(id),audit_id TEXT NOT NULL REFERENCES memory_legacy_deployment_audit(id),request_hash TEXT NOT NULL,outcome_json TEXT NOT NULL CHECK(json_valid(outcome_json)));

CREATE TRIGGER memory_legacy_attempts_immutable BEFORE UPDATE ON memory_legacy_attempts BEGIN SELECT RAISE(ABORT,'legacy ledger immutable'); END;

CREATE TRIGGER memory_legacy_attempts_retained BEFORE DELETE ON memory_legacy_attempts BEGIN SELECT RAISE(ABORT,'legacy ledger retained'); END;

