CREATE TRIGGER memory_legacy_access_audit_retained BEFORE DELETE ON memory_legacy_access_audit BEGIN SELECT RAISE(ABORT,'legacy ledger retained'); END;

CREATE TRIGGER memory_legacy_audit_immutable BEFORE UPDATE ON memory_legacy_audit BEGIN SELECT RAISE(ABORT,'legacy ledger immutable'); END;

CREATE TRIGGER memory_legacy_audit_retained BEFORE DELETE ON memory_legacy_audit BEGIN SELECT RAISE(ABORT,'legacy ledger retained'); END;

