CREATE TRIGGER memory_legacy_ownership_completion_guard BEFORE INSERT ON memory_legacy_ownership_completions WHEN NOT EXISTS(SELECT 1 FROM memory_legacy_ownership_corrections x JOIN memory_legacy_claims claim ON claim.id=x.claim_id JOIN memory_legacy_exposure e ON e.attempt_id=claim.attempt_id JOIN memory_machine_principals p ON p.id=json_extract(x.destination_json,'$.machineId') JOIN memory_machine_grants g ON g.id=p.grant_id AND g.machine_id=p.id JOIN memory_principals generic ON generic.id=p.id JOIN memory_runtime_keys keyrow ON keyrow.machine_id=p.id WHERE x.id=NEW.correction_id AND x.request_hash=NEW.request_hash AND p.installation_id=e.installation_id AND p.repository_id=e.repository_id AND p.status='active' AND generic.status='active' AND g.state='consumed' AND p.grant_id=json_extract(x.destination_json,'$.grantId') AND p.commitment=json_extract(x.destination_json,'$.machineCommitment') AND keyrow.commitment=p.commitment AND p.scope=json_extract(x.destination_json,'$.scope') AND p.revision=json_extract(x.destination_json,'$.machineRevision') AND g.revision=json_extract(x.destination_json,'$.grantRevision') AND json_extract(x.destination_json,'$.credentialGeneration')=(SELECT max(generation) FROM memory_runtime_rotations WHERE machine_id=p.id) AND (x.predecessor_id=claim.id OR EXISTS(SELECT 1 FROM memory_legacy_ownership_corrections old JOIN memory_legacy_ownership_completions done ON done.correction_id=old.id AND done.request_hash=old.request_hash WHERE old.id=x.predecessor_id AND old.claim_id=claim.id))) BEGIN SELECT RAISE(ABORT,'ownership correction requires exact current destination and predecessor'); END;

CREATE VIEW memory_legacy_staging AS SELECT c.*,b.compatibility_audit_id FROM memory_legacy_configuration c JOIN memory_legacy_attempts a ON a.id=c.attempt_id AND a.request_hash=c.request_hash JOIN memory_legacy_baselines b ON b.attempt_id=a.id AND b.baseline_hash=c.baseline_hash JOIN memory_legacy_manifests m ON m.attempt_id=a.id AND m.schema_version=15 WHERE c.state='maintenance' AND a.installation_id=c.installation_id AND a.repository_id=c.repository_id AND a.target_json=c.target_json AND a.pin_hash=c.pin_hash AND EXISTS(SELECT 1 FROM memory_legacy_closures x WHERE x.attempt_id=a.id AND x.inventory_hash=a.inventory_hash);

CREATE VIEW memory_legacy_exposure AS SELECT c.* FROM memory_legacy_configuration c JOIN memory_legacy_completions done ON done.attempt_id=c.attempt_id AND done.request_hash=c.request_hash JOIN memory_legacy_audit audit ON audit.id=done.audit_id AND audit.attempt_id=done.attempt_id AND audit.request_hash=done.request_hash AND audit.closure_id=done.closure_id JOIN memory_legacy_closures closed ON closed.id=done.closure_id AND closed.attempt_id=done.attempt_id JOIN memory_legacy_protocol_transitions transition ON transition.attempt_id=done.attempt_id JOIN memory_legacy_deployments deployment ON deployment.attempt_id=done.attempt_id WHERE c.state='exposed' AND c.final_id=done.attempt_id AND transition.pin_hash=deployment.pin_hash AND transition.protocol_hash=deployment.protocol_hash AND transition.route_contract_hash=deployment.route_contract_hash AND deployment.pin_hash=c.pin_hash;

CREATE VIEW memory_legacy_effective_claims AS WITH base AS (SELECT claim.* FROM memory_legacy_claims claim JOIN memory_legacy_exposure e ON e.attempt_id=claim.attempt_id JOIN memory_legacy_completions done ON done.attempt_id=claim.attempt_id WHERE done.machine_id=claim.machine_id AND done.grant_id=claim.grant_id AND done.key_commitment=claim.key_commitment AND done.scope=claim.scope AND done.machine_revision=claim.machine_revision AND done.grant_revision=claim.grant_revision AND done.credential_generation=claim.credential_generation), latest AS (SELECT x.* FROM memory_legacy_ownership_corrections x JOIN memory_legacy_ownership_completions done ON done.correction_id=x.id AND done.request_hash=x.request_hash WHERE NOT EXISTS(SELECT 1 FROM memory_legacy_ownership_corrections next JOIN memory_legacy_ownership_completions nd ON nd.correction_id=next.id WHERE next.predecessor_id=x.id)) SELECT claim.id,claim.attempt_id,claim.ordinal,claim.kind,claim.original_id,claim.snapshot_hash,claim.evidence_hash,claim.record_json,coalesce(json_extract(latest.destination_json,'$.machineId'),claim.machine_id) machine_id,coalesce(json_extract(latest.destination_json,'$.grantId'),claim.grant_id) grant_id,coalesce(json_extract(latest.destination_json,'$.machineCommitment'),claim.key_commitment) key_commitment,coalesce(json_extract(latest.destination_json,'$.scope'),claim.scope) scope,coalesce(json_extract(latest.destination_json,'$.machineRevision'),claim.machine_revision) machine_revision,coalesce(json_extract(latest.destination_json,'$.grantRevision'),claim.grant_revision) grant_revision,coalesce(json_extract(latest.destination_json,'$.credentialGeneration'),claim.credential_generation) credential_generation,coalesce(latest.visibility,claim.visibility) visibility FROM base claim LEFT JOIN latest ON latest.claim_id=claim.id;

CREATE VIEW memory_legacy_effective_facts AS SELECT f.id,f.slug,f.type,f.body,f.author,f.created_at,f.session_id,coalesce((SELECT correction.new_fact_id FROM memory_legacy_corrections correction JOIN memory_data_completions completed ON completed.attempt_id=correction.attempt_id WHERE correction.old_fact_id=f.id),f.superseded_by) superseded_by,CASE WHEN claim.visibility='shared' AND f.type NOT IN('user','feedback') THEN 1 ELSE 0 END shared,claim.machine_id owner_principal_id,f.source,claim.id legacy_claim_id FROM facts f JOIN memory_legacy_effective_claims claim ON claim.kind='fact' AND claim.original_id=cast(f.id AS TEXT) WHERE f.capture_attempt_id IS NULL UNION ALL SELECT f.id,f.slug,f.type,f.body,f.author,f.created_at,f.session_id,f.superseded_by,f.shared,f.owner_principal_id,f.source,NULL legacy_claim_id FROM facts f JOIN memory_data_fact_links l ON l.fact_id=f.id JOIN memory_data_completions done ON done.attempt_id=l.attempt_id;

CREATE VIEW memory_legacy_effective_sessions AS SELECT s.id,s.agent,s.author,s.machine,s.branch,s.cwd,s.started_at,s.ended_at,s.status,s.reason,s.read_through,s.raw_key,s.raw_bytes,s.updated_at,claim.machine_id owner_principal_id,claim.id legacy_claim_id FROM sessions s JOIN memory_legacy_effective_claims claim ON claim.kind='session' AND claim.original_id=s.id WHERE s.capture_attempt_id IS NULL UNION ALL SELECT s.id,s.agent,s.author,s.machine,s.branch,s.cwd,s.started_at,s.ended_at,s.status,s.reason,s.read_through,s.raw_key,s.raw_bytes,s.updated_at,s.owner_principal_id,NULL legacy_claim_id FROM sessions s JOIN memory_data_session_owners o ON o.session_id=s.id WHERE EXISTS(SELECT 1 FROM memory_data_session_events event JOIN memory_data_completions done ON done.attempt_id=event.attempt_id WHERE event.session_id=s.id);

CREATE TRIGGER memory_legacy_configuration_guard BEFORE UPDATE ON memory_legacy_configuration WHEN NEW.installation_id IS NOT OLD.installation_id OR NEW.repository_id IS NOT OLD.repository_id OR NEW.attempt_id IS NOT OLD.attempt_id OR NEW.request_hash IS NOT OLD.request_hash OR NEW.baseline_hash IS NOT OLD.baseline_hash OR NEW.target_json IS NOT OLD.target_json OR NEW.pin_hash IS NOT OLD.pin_hash OR NOT(OLD.state='maintenance' AND NEW.state='exposed' AND NEW.revision=OLD.revision+1 AND NEW.final_id=OLD.attempt_id AND EXISTS(SELECT 1 FROM memory_legacy_completions done JOIN memory_legacy_attempts legacyattempt ON legacyattempt.id=done.attempt_id JOIN memory_legacy_audit audit ON audit.id=done.audit_id AND audit.attempt_id=done.attempt_id AND audit.request_hash=done.request_hash AND audit.closure_id=done.closure_id JOIN memory_legacy_manifests manifest ON manifest.attempt_id=done.attempt_id JOIN memory_legacy_protocol_transitions transition ON transition.attempt_id=done.attempt_id AND transition.protocol_hash=manifest.protocol_hash AND transition.route_contract_hash=manifest.route_contract_hash AND transition.pin_hash=OLD.pin_hash JOIN memory_legacy_deployments deployment ON deployment.attempt_id=done.attempt_id AND deployment.predecessor_id=legacyattempt.predecessor_id AND deployment.pin_hash=transition.pin_hash AND deployment.protocol_hash=transition.protocol_hash AND deployment.route_contract_hash=transition.route_contract_hash AND deployment.source_hash=transition.source_hash JOIN memory_machine_principals machine ON machine.id=done.machine_id JOIN memory_machine_grants grantrow ON grantrow.id=done.grant_id AND grantrow.machine_id=machine.id JOIN memory_principals generic ON generic.id=machine.id JOIN memory_runtime_keys keyrow ON keyrow.machine_id=machine.id WHERE done.attempt_id=OLD.attempt_id AND done.request_hash=OLD.request_hash AND machine.status='active' AND generic.status='active' AND grantrow.state='consumed' AND machine.revision=done.machine_revision AND grantrow.revision=done.grant_revision AND keyrow.commitment=done.key_commitment AND machine.scope=done.scope AND done.credential_generation=(SELECT max(generation) FROM memory_runtime_rotations WHERE machine_id=machine.id) AND EXISTS(SELECT 1 FROM memory_runtime_rotations rotation JOIN memory_runtime_completions receipt ON receipt.attempt_id=rotation.attempt_id JOIN memory_runtime_attempts attempt ON attempt.id=receipt.attempt_id AND attempt.request_hash=receipt.request_hash AND attempt.audit_id=receipt.audit_id JOIN memory_runtime_audit proof ON proof.id=receipt.audit_id AND proof.attempt_id=attempt.id AND proof.request_hash=attempt.request_hash WHERE rotation.machine_id=machine.id AND rotation.grant_id=grantrow.id AND rotation.generation=done.credential_generation AND rotation.expires_at>unixepoch() AND rotation.scope=done.scope AND rotation.machine_revision=machine.revision AND rotation.grant_revision=grantrow.revision) AND EXISTS(SELECT 1 FROM memory_legacy_closures closed WHERE closed.id=done.closure_id AND closed.attempt_id=done.attempt_id AND closed.observed_at<=unixepoch() AND closed.observed_at>unixepoch()-120))) BEGIN SELECT RAISE(ABORT,'legacy exposure requires exact completion'); END;

CREATE TRIGGER memory_legacy_claim_guard BEFORE INSERT ON memory_legacy_claims WHEN NOT EXISTS(SELECT 1 FROM memory_legacy_staging s JOIN memory_legacy_pieces p ON p.attempt_id=s.attempt_id AND p.ordinal=NEW.ordinal JOIN json_each(p.payload_json) j WHERE s.attempt_id=NEW.attempt_id AND json_extract(j.value,'$.id')=NEW.id AND json_extract(j.value,'$.kind')=NEW.kind AND json_extract(j.value,'$.originalId')=NEW.original_id AND json_extract(j.value,'$.snapshotHash')=NEW.snapshot_hash AND json_extract(j.value,'$.recordJson')=NEW.record_json AND json_extract(j.value,'$.evidenceHash')=NEW.evidence_hash AND json_extract(j.value,'$.machineId')=NEW.machine_id AND json_extract(j.value,'$.grantId')=NEW.grant_id AND json_extract(j.value,'$.keyCommitment')=NEW.key_commitment AND json_extract(j.value,'$.scope')=NEW.scope AND json_extract(j.value,'$.machineRevision')=NEW.machine_revision AND json_extract(j.value,'$.grantRevision')=NEW.grant_revision AND json_extract(j.value,'$.credentialGeneration')=NEW.credential_generation AND json_extract(j.value,'$.visibility')=NEW.visibility) BEGIN SELECT RAISE(ABORT,'claim requires reviewed piece'); END;

CREATE TRIGGER memory_legacy_completion_guard BEFORE INSERT ON memory_legacy_completions WHEN NOT EXISTS(SELECT 1 FROM memory_legacy_staging s JOIN memory_legacy_attempts a ON a.id=s.attempt_id JOIN memory_legacy_audit audit ON audit.id=NEW.audit_id AND audit.attempt_id=a.id AND audit.request_hash=a.request_hash AND audit.closure_id=NEW.closure_id JOIN memory_legacy_closures closed ON closed.id=NEW.closure_id AND closed.attempt_id=a.id JOIN memory_machine_principals p ON p.id=NEW.machine_id JOIN memory_machine_grants g ON g.id=p.grant_id AND g.machine_id=p.id JOIN memory_runtime_keys k ON k.machine_id=p.id JOIN memory_principals generic ON generic.id=p.id AND generic.status='active' WHERE a.id=NEW.attempt_id AND a.request_hash=NEW.request_hash AND a.universe_hash=NEW.universe_hash AND p.installation_id=s.installation_id AND p.repository_id=s.repository_id AND p.grant_id=NEW.grant_id AND p.commitment=NEW.key_commitment AND k.commitment=p.commitment AND p.scope=NEW.scope AND p.status='active' AND g.state='consumed' AND p.revision=NEW.machine_revision AND g.revision=NEW.grant_revision AND NEW.credential_generation=(SELECT max(generation) FROM memory_runtime_rotations WHERE machine_id=p.id) AND EXISTS(SELECT 1 FROM memory_runtime_rotations rotation JOIN memory_runtime_completions completion ON completion.attempt_id=rotation.attempt_id WHERE rotation.machine_id=p.id AND rotation.grant_id=g.id AND rotation.generation=NEW.credential_generation AND rotation.expires_at>unixepoch()) AND NEW.claim_count=(SELECT count(*) FROM memory_legacy_claims WHERE attempt_id=a.id) AND NEW.piece_count=(SELECT count(*) FROM memory_legacy_pieces WHERE attempt_id=a.id) AND NEW.quarantine_count=(SELECT count(*) FROM memory_legacy_quarantine WHERE attempt_id=a.id) AND NEW.claim_count+NEW.quarantine_count=json_array_length(a.universe_json) AND NOT EXISTS(SELECT 1 FROM json_each(a.universe_json) u WHERE (SELECT count(*) FROM memory_legacy_claims claim WHERE claim.attempt_id=a.id AND claim.kind=json_extract(u.value,'$.kind') AND claim.original_id=json_extract(u.value,'$.id') AND claim.snapshot_hash=json_extract(u.value,'$.snapshotHash'))+(SELECT count(*) FROM memory_legacy_quarantine q WHERE q.attempt_id=a.id AND q.kind=json_extract(u.value,'$.kind') AND q.original_id=json_extract(u.value,'$.id') AND q.snapshot_hash=json_extract(u.value,'$.snapshotHash'))!=1) AND closed.observed_at<=unixepoch() AND closed.observed_at>unixepoch()-120) BEGIN SELECT RAISE(ABORT,'legacy completion requires exact current grant and universe'); END;

DROP TRIGGER memory_runtime_bootstrap_guard;

CREATE TRIGGER memory_runtime_bootstrap_guard BEFORE INSERT ON memory_runtime_bootstrap WHEN (NOT EXISTS(SELECT 1 FROM memory_runtime_configuration r JOIN memory_machine_configuration c USING(installation_id)JOIN memory_machine_bootstrap_completions old ON old.installation_id=c.installation_id JOIN memory_machine_manifest_receipts oldm ON oldm.installation_id=c.installation_id AND oldm.schema_version=12 JOIN memory_machine_audit olda ON olda.id=old.audit_id AND olda.action='bootstrap' JOIN memory_runtime_manifests m ON m.installation_id=r.installation_id AND m.repository_id=r.repository_id JOIN memory_runtime_audit a ON a.id=m.audit_id AND a.action='upgrade' AND a.attempt_id=r.operation_id WHERE r.installation_id=NEW.installation_id AND r.operation_id=NEW.operation_id AND r.request_hash=NEW.request_hash AND r.baseline_hash=NEW.baseline_hash AND m.baseline_hash=r.baseline_hash AND m.schema_version=13 AND m.request_hash=r.request_hash AND NEW.audit_id=a.id AND a.target_id=r.installation_id AND a.request_hash=r.request_hash AND c.state='pending' AND c.barrier_attempt_id IS NULL AND old.audit_id=r.baseline_audit_id AND old.request_hash=c.request_hash AND oldm.request_hash=c.request_hash AND oldm.audit_id=olda.id AND r.baseline_request_hash=c.request_hash AND olda.request_hash=c.request_hash AND olda.target_id=c.installation_id AND old.operation_id=c.operation_id AND r.pin_hash=c.pin_hash AND r.target_json=c.target_json AND r.runtime_revision=1 AND r.state='pending' AND r.barrier_attempt_id IS NULL)) AND NOT(EXISTS(SELECT 1 FROM memory_legacy_staging legacy JOIN memory_runtime_configuration r USING(installation_id) JOIN memory_machine_configuration c USING(installation_id) JOIN memory_legacy_baselines baseline USING(installation_id) JOIN memory_machine_audit witness ON witness.id=baseline.compatibility_audit_id AND witness.action='issue' JOIN memory_machine_attempts issue ON issue.id=witness.attempt_id AND issue.id=baseline.compatibility_attempt_id JOIN memory_machine_completions completed ON completed.attempt_id=issue.id AND completed.audit_id=witness.id AND completed.request_hash=issue.request_hash JOIN memory_runtime_manifests m USING(installation_id) JOIN memory_runtime_audit a ON a.id=NEW.audit_id WHERE r.installation_id=NEW.installation_id AND r.operation_id=NEW.operation_id AND r.request_hash=NEW.request_hash AND r.baseline_hash=NEW.baseline_hash AND r.baseline_hash=baseline.baseline_hash AND r.baseline_audit_id=witness.id AND r.baseline_request_hash=c.request_hash AND issue.action='issue' AND issue.installation_id=r.installation_id AND witness.request_hash=issue.request_hash AND witness.target_id=issue.target_id AND a.action='upgrade' AND a.attempt_id=r.operation_id AND a.request_hash=r.request_hash AND a.target_id=r.installation_id AND m.audit_id=a.id AND m.request_hash=r.request_hash AND m.schema_version=13 AND m.baseline_hash=r.baseline_hash AND c.state='pending' AND c.barrier_attempt_id IS NULL AND r.pin_hash=c.pin_hash AND r.target_json=c.target_json AND r.runtime_revision=1 AND r.state='pending' AND r.barrier_attempt_id IS NULL)) BEGIN SELECT RAISE(ABORT,'runtime bootstrap requires original completed12'); END;

DROP TRIGGER memory_runtime_activations_guard;

CREATE TRIGGER memory_runtime_activations_guard BEFORE INSERT ON memory_runtime_activations WHEN NOT EXISTS(SELECT 1 FROM memory_runtime_attempts a JOIN memory_runtime_configuration r USING(installation_id)JOIN memory_machine_configuration c USING(installation_id)WHERE a.id=NEW.attempt_id AND a.action='activate' AND a.installation_id=NEW.installation_id AND r.baseline_hash=NEW.baseline_hash AND r.pin_hash=NEW.pin_hash AND r.state='maintenance' AND r.barrier_attempt_id=a.id AND r.runtime_revision=a.runtime_revision+1 AND c.state='pending' AND c.barrier_attempt_id IS NULL AND c.auth_revision=a.auth_revision AND NEW.auth_revision=c.auth_revision AND c.pin_hash=a.pin_hash AND c.pin_revision=a.pin_revision AND r.baseline_hash=a.baseline_hash AND NEW.protocol_hash=json_extract(a.payload_json,'$.protocolHash')AND NEW.route_contract_hash=json_extract(a.payload_json,'$.routeContractHash')AND ((NOT EXISTS(SELECT 1 FROM memory_keys)AND NOT EXISTS(SELECT 1 FROM memory_admins)AND NOT EXISTS(SELECT 1 FROM memory_credentials)AND NOT EXISTS(SELECT 1 FROM memory_devices)AND NOT EXISTS(SELECT 1 FROM memory_identity_bindings)AND NOT EXISTS(SELECT 1 FROM memory_memberships)AND NOT EXISTS(SELECT 1 FROM memory_providers)AND NOT EXISTS(SELECT 1 FROM memory_owner_intents)AND NOT EXISTS(SELECT 1 FROM memory_installation_configuration)AND NOT EXISTS(SELECT 1 FROM memory_bootstrap_completion)AND NOT EXISTS(SELECT 1 FROM memory_schema_receipts)) OR (1 AND (NOT EXISTS(SELECT 1 FROM memory_keys) AND NOT EXISTS(SELECT 1 FROM memory_credentials credential JOIN memory_devices device ON device.id=credential.device_id WHERE device.status='active') AND (EXISTS(SELECT 1 FROM memory_legacy_staging legacy WHERE legacy.installation_id=a.installation_id) OR EXISTS(SELECT 1 FROM memory_legacy_exposure legacy WHERE legacy.installation_id=a.installation_id))))))BEGIN SELECT RAISE(ABORT,'runtime activation requires exact fresh authority'); END;

DROP VIEW memory_runtime_outcomes;

CREATE VIEW memory_runtime_outcomes AS SELECT a.id,a.installation_id,a.request_hash,a.audit_id,a.action,a.target_id,c.auth_revision,r.runtime_revision FROM memory_runtime_attempts a JOIN memory_runtime_configuration r USING(installation_id)JOIN memory_machine_configuration c USING(installation_id)WHERE c.state='pending' AND c.barrier_attempt_id IS NULL AND r.pin_hash=a.pin_hash AND c.pin_hash=a.pin_hash AND c.pin_revision=a.pin_revision AND r.baseline_hash=a.baseline_hash AND c.auth_revision=a.auth_revision+CASE WHEN a.action IN('issue','enroll','revoke')THEN 1 ELSE 0 END AND r.runtime_revision=a.runtime_revision+1 AND((a.action='issue' AND EXISTS(SELECT 1 FROM memory_machine_completions d JOIN memory_machine_attempts la ON la.id=d.attempt_id JOIN memory_machine_audit audit ON audit.id=d.audit_id WHERE d.attempt_id=a.id AND d.request_hash=a.request_hash AND d.audit_id=a.audit_id AND d.auth_revision=c.auth_revision AND la.payload_json=a.payload_json AND la.action=a.action AND audit.target_id=a.target_id)AND EXISTS(SELECT 1 FROM memory_machine_grants g WHERE g.id=a.target_id AND g.state='pending' AND g.revision=1 AND g.issued_attempt_id=a.id AND g.commitment=json_extract(a.payload_json,'$.machineCommitment')AND g.secret_hash=json_extract(a.payload_json,'$.capabilityHash')AND g.scope=json_extract(a.payload_json,'$.scope')AND g.expires_at=json_extract(a.payload_json,'$.expiresAt')AND g.expires_at>unixepoch()))OR(a.action='revoke' AND EXISTS(SELECT 1 FROM memory_machine_completions d JOIN memory_machine_attempts la ON la.id=d.attempt_id JOIN memory_machine_audit audit ON audit.id=d.audit_id WHERE d.attempt_id=a.id AND d.request_hash=a.request_hash AND d.audit_id=a.audit_id AND d.auth_revision=c.auth_revision AND la.payload_json=a.payload_json AND la.action=a.action AND audit.target_id=a.target_id)AND EXISTS(SELECT 1 FROM memory_machine_principals p JOIN memory_machine_grants g ON g.id=p.grant_id JOIN memory_principals generic ON generic.id=p.id AND generic.status='removed' WHERE p.id=a.target_id AND p.installation_id=a.installation_id AND p.repository_id=r.repository_id AND p.status='revoked' AND p.revision=json_extract(a.payload_json,'$.machineRevision')+1 AND g.state='revoked' AND g.machine_id=p.id AND g.revision=json_extract(a.payload_json,'$.grantRevision')+1))OR(a.action='enroll' AND EXISTS(SELECT 1 FROM memory_machine_completions d JOIN memory_machine_attempts la ON la.id=d.attempt_id JOIN memory_machine_audit audit ON audit.id=d.audit_id WHERE d.attempt_id=a.id AND d.request_hash=a.request_hash AND d.audit_id=a.audit_id AND d.auth_revision=c.auth_revision AND la.payload_json=a.payload_json AND la.action=a.action AND audit.target_id=a.target_id)AND EXISTS(SELECT 1 FROM memory_machine_principals p JOIN memory_machine_grants g ON g.id=p.grant_id JOIN memory_principals generic ON generic.id=p.id AND generic.installation_id=p.installation_id WHERE p.id=json_extract(a.payload_json,'$.machineId')AND p.installation_id=a.installation_id AND p.repository_id=r.repository_id AND p.status='active' AND generic.status='active' AND g.state='consumed' AND g.machine_id=p.id AND g.installation_id=p.installation_id AND g.repository_id=p.repository_id AND g.id=json_extract(a.payload_json,'$.grantId')AND p.scope=json_extract(a.payload_json,'$.scope')AND g.revision=json_extract(a.payload_json,'$.grantRevision')AND p.revision=json_extract(a.payload_json,'$.machineRevision'))AND EXISTS(SELECT 1 FROM memory_runtime_proofs p WHERE p.attempt_id=a.id AND p.nonce_hash=json_extract(a.payload_json,'$.nonceHash')AND p.proof_hash=json_extract(a.payload_json,'$.proofHash')AND p.deadline>unixepoch()AND p.deadline=json_extract(a.payload_json,'$.deadline')AND p.machine_id=a.target_id AND p.grant_id=json_extract(a.payload_json,'$.grantId')AND p.commitment=json_extract(a.payload_json,'$.machineCommitment'))AND EXISTS(SELECT 1 FROM memory_runtime_rotations k WHERE k.attempt_id=a.id AND k.hash=json_extract(a.payload_json,'$.credentialHash')AND k.generation=json_extract(a.payload_json,'$.generation')AND k.machine_id=a.target_id AND k.scope=json_extract(a.payload_json,'$.scope')AND k.expires_at>unixepoch()AND k.grant_id=json_extract(a.payload_json,'$.grantId')AND k.grant_revision=json_extract(a.payload_json,'$.grantRevision')AND k.machine_revision=json_extract(a.payload_json,'$.machineRevision')AND k.previous_hash IS json_extract(a.payload_json,'$.previousHash')AND k.overlap_until=json_extract(a.payload_json,'$.overlapUntil')AND k.expires_at=json_extract(a.payload_json,'$.credentialExpiresAt'))AND EXISTS(SELECT 1 FROM memory_runtime_keys k WHERE k.machine_id=a.target_id AND k.attempt_id=a.id AND k.commitment=json_extract(a.payload_json,'$.machineCommitment')AND k.public_key_json=json_extract(a.payload_json,'$.publicKeyJson')))OR(a.action='renew' AND EXISTS(SELECT 1 FROM memory_machine_principals p JOIN memory_machine_grants g ON g.id=p.grant_id JOIN memory_principals generic ON generic.id=p.id AND generic.installation_id=p.installation_id WHERE p.id=json_extract(a.payload_json,'$.machineId')AND p.installation_id=a.installation_id AND p.repository_id=r.repository_id AND p.status='active' AND generic.status='active' AND g.state='consumed' AND g.machine_id=p.id AND g.installation_id=p.installation_id AND g.repository_id=p.repository_id AND g.id=json_extract(a.payload_json,'$.grantId')AND p.scope=json_extract(a.payload_json,'$.scope')AND g.revision=json_extract(a.payload_json,'$.grantRevision')AND p.revision=json_extract(a.payload_json,'$.machineRevision'))AND EXISTS(SELECT 1 FROM memory_runtime_proofs p WHERE p.attempt_id=a.id AND p.nonce_hash=json_extract(a.payload_json,'$.nonceHash')AND p.proof_hash=json_extract(a.payload_json,'$.proofHash')AND p.deadline>unixepoch()AND p.deadline=json_extract(a.payload_json,'$.deadline')AND p.machine_id=a.target_id AND p.grant_id=json_extract(a.payload_json,'$.grantId')AND p.commitment=json_extract(a.payload_json,'$.machineCommitment'))AND EXISTS(SELECT 1 FROM memory_runtime_rotations k WHERE k.attempt_id=a.id AND k.hash=json_extract(a.payload_json,'$.credentialHash')AND k.generation=json_extract(a.payload_json,'$.generation')AND k.machine_id=a.target_id AND k.scope=json_extract(a.payload_json,'$.scope')AND k.expires_at>unixepoch()AND k.grant_id=json_extract(a.payload_json,'$.grantId')AND k.grant_revision=json_extract(a.payload_json,'$.grantRevision')AND k.machine_revision=json_extract(a.payload_json,'$.machineRevision')AND k.previous_hash IS json_extract(a.payload_json,'$.previousHash')AND k.overlap_until=json_extract(a.payload_json,'$.overlapUntil')AND k.expires_at=json_extract(a.payload_json,'$.credentialExpiresAt'))AND EXISTS(SELECT 1 FROM memory_runtime_keys stored_key WHERE stored_key.machine_id=a.target_id AND stored_key.commitment=json_extract(a.payload_json,'$.machineCommitment')AND stored_key.public_key_json=json_extract(a.payload_json,'$.publicKeyJson')))OR(a.action='activate' AND EXISTS(SELECT 1 FROM memory_runtime_activations x WHERE x.attempt_id=a.id AND x.installation_id=a.installation_id AND x.baseline_hash=r.baseline_hash AND x.pin_hash=r.pin_hash AND x.auth_revision=c.auth_revision AND x.protocol_hash=json_extract(a.payload_json,'$.protocolHash')AND x.route_contract_hash=json_extract(a.payload_json,'$.routeContractHash'))AND ((NOT EXISTS(SELECT 1 FROM memory_keys)AND NOT EXISTS(SELECT 1 FROM memory_admins)AND NOT EXISTS(SELECT 1 FROM memory_credentials)AND NOT EXISTS(SELECT 1 FROM memory_devices)AND NOT EXISTS(SELECT 1 FROM memory_identity_bindings)AND NOT EXISTS(SELECT 1 FROM memory_memberships)AND NOT EXISTS(SELECT 1 FROM memory_providers)AND NOT EXISTS(SELECT 1 FROM memory_owner_intents)AND NOT EXISTS(SELECT 1 FROM memory_installation_configuration)AND NOT EXISTS(SELECT 1 FROM memory_bootstrap_completion)AND NOT EXISTS(SELECT 1 FROM memory_schema_receipts)) OR (1 AND (NOT EXISTS(SELECT 1 FROM memory_keys) AND NOT EXISTS(SELECT 1 FROM memory_credentials credential JOIN memory_devices device ON device.id=credential.device_id WHERE device.status='active') AND (EXISTS(SELECT 1 FROM memory_legacy_staging legacy WHERE legacy.installation_id=a.installation_id) OR EXISTS(SELECT 1 FROM memory_legacy_exposure legacy WHERE legacy.installation_id=a.installation_id))))))OR(a.action IN('stage','publish')AND EXISTS(SELECT 1 FROM memory_machine_principals p JOIN memory_machine_grants g ON g.id=p.grant_id JOIN memory_principals generic ON generic.id=p.id AND generic.installation_id=p.installation_id WHERE p.id=json_extract(a.payload_json,'$.machineId')AND p.installation_id=a.installation_id AND p.repository_id=r.repository_id AND p.status='active' AND generic.status='active' AND g.state='consumed' AND g.machine_id=p.id AND g.installation_id=p.installation_id AND g.repository_id=p.repository_id AND g.id=json_extract(a.payload_json,'$.grantId')AND p.scope=json_extract(a.payload_json,'$.scope')AND g.revision=json_extract(a.payload_json,'$.grantRevision')AND p.revision=json_extract(a.payload_json,'$.machineRevision'))AND EXISTS(SELECT 1 FROM memory_runtime_proofs p WHERE p.attempt_id=a.id AND p.nonce_hash=json_extract(a.payload_json,'$.nonceHash')AND p.proof_hash=json_extract(a.payload_json,'$.proofHash')AND p.deadline>unixepoch()AND p.deadline=json_extract(a.payload_json,'$.deadline')AND p.machine_id=a.target_id AND p.grant_id=json_extract(a.payload_json,'$.grantId')AND p.commitment=json_extract(a.payload_json,'$.machineCommitment'))AND EXISTS(SELECT 1 FROM memory_runtime_transcripts x WHERE x.attempt_id=a.id AND x.machine_id=a.target_id AND x.object_hash=json_extract(a.payload_json,'$.objectHash')AND x.content_hash=json_extract(a.payload_json,'$.contentHash')AND x.session_hash=json_extract(a.payload_json,'$.sessionHash')AND x.visibility=json_extract(a.payload_json,'$.visibility')AND x.auth_revision=c.auth_revision AND x.grant_revision=json_extract(a.payload_json,'$.grantRevision')AND x.machine_revision=json_extract(a.payload_json,'$.machineRevision')AND x.credential_generation=json_extract(a.payload_json,'$.credentialGeneration')AND x.credential_generation=(SELECT max(generation)FROM memory_runtime_rotations WHERE machine_id=x.machine_id)AND x.event=CASE WHEN a.action='stage' THEN 'staged' ELSE 'published' END)));

CREATE TRIGGER memory_legacy_memory_data_attempts_barrier BEFORE INSERT ON memory_data_attempts WHEN NOT EXISTS(SELECT 1 FROM memory_legacy_exposure e WHERE e.installation_id=NEW.installation_id) BEGIN SELECT RAISE(ABORT,'legacy maintenance barrier'); END;

CREATE TRIGGER memory_legacy_imported_session_immutable BEFORE UPDATE ON sessions WHEN EXISTS(SELECT 1 FROM memory_legacy_claims claim WHERE claim.kind='session' AND claim.original_id=OLD.id) BEGIN SELECT RAISE(ABORT,'imported session immutable; continue in a fresh namespace'); END;

CREATE TRIGGER memory_legacy_imported_fact_immutable BEFORE UPDATE ON facts WHEN EXISTS(SELECT 1 FROM memory_legacy_claims claim WHERE claim.kind='fact' AND claim.original_id=cast(OLD.id AS TEXT)) BEGIN SELECT RAISE(ABORT,'imported authored fact immutable'); END;

CREATE TRIGGER memory_legacy_correction_guard BEFORE INSERT ON memory_legacy_corrections WHEN NOT EXISTS(SELECT 1 FROM memory_data_capture_authority a JOIN memory_data_fact_links link ON link.attempt_id=a.id AND link.ordinal=NEW.ordinal JOIN json_each(a.payload_json,'$.facts') fact ON fact.key=link.ordinal JOIN json_each(fact.value,'$.supersedes') superseded ON superseded.value=NEW.old_fact_id JOIN memory_legacy_effective_claims claim ON claim.id=NEW.claim_id AND claim.kind='fact' AND claim.original_id=cast(NEW.old_fact_id AS TEXT) JOIN facts old ON old.id=NEW.old_fact_id WHERE a.id=NEW.attempt_id AND link.fact_id=NEW.new_fact_id AND link.machine_id=NEW.machine_id AND NEW.predecessor_id=claim.id AND old.superseded_by IS NULL AND NOT EXISTS(SELECT 1 FROM memory_legacy_corrections previous JOIN memory_data_completions done ON done.attempt_id=previous.attempt_id WHERE previous.old_fact_id=old.id) AND (claim.machine_id=link.machine_id OR EXISTS(SELECT 1 FROM memory_machine_principals admin WHERE admin.id=link.machine_id AND admin.installation_id=a.installation_id AND admin.repository_id=json_extract(a.payload_json,'$.repositoryId') AND admin.status='active' AND admin.scope='memory:read memory:write memory:admin'))) BEGIN SELECT RAISE(ABORT,'correction requires owned imported predecessor and exact capture'); END;

DROP VIEW memory_data_verified_captures;

CREATE VIEW memory_data_verified_captures AS SELECT a.id,json_object('action','capture','attemptId',a.id,'tags',json(json_extract(a.payload_json,'$.newTags')),'facts',json((SELECT json_group_array(json_object('ordinal',ordinal,'factId',fact_id))FROM(SELECT ordinal,fact_id FROM memory_data_fact_links WHERE attempt_id=a.id ORDER BY ordinal))),'session',json(CASE WHEN json_type(a.payload_json,'$.session')='null' THEN 'null' ELSE json_object('id',json_extract(a.payload_json,'$.session.id'),'previousCursor',json_extract(a.payload_json,'$.session.previousCursor'),'nextCursor',json_extract(a.payload_json,'$.session.nextCursor'))END),'supersedes',json((SELECT json_group_array(json_object('factId',old_fact_id,'ordinal',ordinal,'newFactId',new_fact_id))FROM(SELECT x.old_fact_id,x.ordinal,x.new_fact_id FROM json_each(a.payload_json,'$.facts')j JOIN json_each(j.value,'$.supersedes')old JOIN memory_data_supersedes x ON x.attempt_id=a.id AND x.ordinal=j.key AND x.old_fact_id=old.value ORDER BY j.key,old.key))),'run',json(CASE WHEN json_type(a.payload_json,'$.run')='null' THEN 'null' ELSE(SELECT json_object('id',run_id,'counts',json(json_extract(a.payload_json,'$.run.counts')))FROM memory_data_runs WHERE attempt_id=a.id)END))outcome_json FROM memory_data_capture_authority a WHERE(SELECT count(*)FROM memory_data_tag_definitions WHERE attempt_id=a.id)=json_array_length(a.payload_json,'$.newTags')AND NOT EXISTS(SELECT 1 FROM json_each(a.payload_json,'$.newTags')j WHERE NOT EXISTS(SELECT 1 FROM memory_data_tag_definitions l JOIN tags t ON t.name=l.name WHERE l.attempt_id=a.id AND l.tag_json=j.value AND t.name=json_extract(j.value,'$.name')AND t.definition=json_extract(j.value,'$.definition')AND t.alias_of IS json_extract(j.value,'$.aliasOf')))AND(SELECT count(*)FROM memory_data_fact_links WHERE attempt_id=a.id)=json_array_length(a.payload_json,'$.facts')AND(SELECT count(*)FROM facts WHERE capture_attempt_id=a.id)=json_array_length(a.payload_json,'$.facts')AND NOT EXISTS(SELECT 1 FROM json_each(a.payload_json,'$.facts')j WHERE NOT EXISTS(SELECT 1 FROM memory_data_fact_links l JOIN facts f ON f.id=l.fact_id WHERE l.attempt_id=a.id AND l.ordinal=j.key AND l.fact_json=j.value AND l.machine_id=json_extract(a.payload_json,'$.machineId')AND f.owner_principal_id=l.machine_id AND f.capture_attempt_id=a.id AND f.capture_ordinal=j.key AND f.slug=json_extract(j.value,'$.slug')AND f.type=json_extract(j.value,'$.type')AND f.body=json_extract(j.value,'$.body')AND f.session_id=json_extract(a.payload_json,'$.session.id')AND f.source=json_extract(a.payload_json,'$.source')AND f.source IN('save','backfill','consolidation')AND f.author=l.machine_id AND f.created_at=json_extract(a.payload_json,'$.session.updatedAt')AND f.shared=CASE WHEN json_extract(a.payload_json,'$.visibility')='shared' AND f.type NOT IN('user','feedback')THEN 1 ELSE 0 END AND(SELECT count(*)FROM fact_tags WHERE fact_id=f.id)=json_array_length(j.value,'$.tags')AND(SELECT count(*)FROM memory_data_tag_links WHERE attempt_id=a.id AND ordinal=j.key)=json_array_length(j.value,'$.tags')AND NOT EXISTS(SELECT 1 FROM json_each(j.value,'$.tags')t WHERE NOT EXISTS(SELECT 1 FROM fact_tags ft JOIN memory_data_tag_links tl ON tl.tag=ft.tag AND tl.attempt_id=a.id AND tl.ordinal=j.key WHERE ft.fact_id=f.id AND ft.tag=t.value))))AND(SELECT count(*)FROM memory_data_supersedes WHERE attempt_id=a.id)=(SELECT coalesce(sum(json_array_length(j.value,'$.supersedes')),0)FROM json_each(a.payload_json,'$.facts')j)AND (NOT EXISTS(SELECT 1 FROM json_each(a.payload_json,'$.facts')j JOIN json_each(j.value,'$.supersedes')old WHERE NOT EXISTS(SELECT 1 FROM memory_data_supersedes x JOIN memory_data_fact_links l ON l.attempt_id=x.attempt_id AND l.ordinal=x.ordinal JOIN facts f ON f.id=x.old_fact_id WHERE x.attempt_id=a.id AND x.ordinal=j.key AND x.old_fact_id=old.value AND x.new_fact_id=l.fact_id AND f.superseded_by=x.new_fact_id AND(f.owner_principal_id=x.machine_id OR EXISTS(SELECT 1 FROM memory_machine_principals admin JOIN memory_machine_principals owner ON owner.id=f.owner_principal_id AND owner.installation_id=admin.installation_id AND owner.repository_id=admin.repository_id WHERE admin.id=x.machine_id AND admin.status='active' AND admin.scope='memory:read memory:write memory:admin'))AND x.machine_id=json_extract(a.payload_json,'$.machineId')AND f.id IN(SELECT oldlink.fact_id FROM memory_data_fact_links oldlink JOIN memory_data_attempts olda ON olda.id=oldlink.attempt_id WHERE olda.installation_id=a.installation_id))) OR NOT EXISTS(SELECT 1 FROM json_each(a.payload_json,'$.facts') j JOIN json_each(j.value,'$.supersedes') old WHERE NOT EXISTS(SELECT 1 FROM memory_data_supersedes x JOIN memory_data_fact_links link ON link.attempt_id=x.attempt_id AND link.ordinal=x.ordinal JOIN memory_legacy_effective_facts f ON f.id=x.old_fact_id WHERE x.attempt_id=a.id AND x.ordinal=j.key AND x.old_fact_id=old.value AND x.new_fact_id=link.fact_id AND x.machine_id=json_extract(a.payload_json,'$.machineId') AND (f.owner_principal_id=x.machine_id OR EXISTS(SELECT 1 FROM memory_machine_principals admin WHERE admin.id=x.machine_id AND admin.installation_id=a.installation_id AND admin.repository_id=json_extract(a.payload_json,'$.repositoryId') AND admin.status='active' AND admin.scope='memory:read memory:write memory:admin')) AND ((f.legacy_claim_id IS NULL AND f.superseded_by=x.new_fact_id) OR EXISTS(SELECT 1 FROM memory_legacy_corrections correction WHERE correction.attempt_id=x.attempt_id AND correction.old_fact_id=x.old_fact_id AND correction.new_fact_id=x.new_fact_id AND correction.ordinal=x.ordinal AND correction.machine_id=x.machine_id AND correction.claim_id=f.legacy_claim_id AND correction.predecessor_id=f.legacy_claim_id)))))AND((json_type(a.payload_json,'$.session')='null' AND NOT EXISTS(SELECT 1 FROM memory_data_session_events WHERE attempt_id=a.id))OR EXISTS(SELECT 1 FROM memory_data_session_events e JOIN sessions sess ON sess.id=e.session_id JOIN memory_data_session_owners o ON o.session_id=sess.id WHERE e.attempt_id=a.id AND e.session_json=json_extract(a.payload_json,'$.session')AND e.session_id=json_extract(a.payload_json,'$.session.id')AND e.machine_id=json_extract(a.payload_json,'$.machineId')AND o.machine_id=e.machine_id AND o.installation_id=a.installation_id AND o.repository_id=json_extract(a.payload_json,'$.repositoryId')AND sess.owner_principal_id=e.machine_id AND e.previous_cursor IS json_extract(a.payload_json,'$.session.previousCursor')AND e.next_cursor IS json_extract(a.payload_json,'$.session.nextCursor')AND sess.read_through IS e.next_cursor AND sess.capture_attempt_id=a.id AND sess.status=json_extract(a.payload_json,'$.session.status')AND sess.reason IS json_extract(a.payload_json,'$.session.reason')AND sess.agent=json_extract(a.payload_json,'$.session.agent')AND sess.updated_at=json_extract(a.payload_json,'$.session.updatedAt')AND sess.branch IS json_extract(a.payload_json,'$.session.branch')AND sess.cwd IS json_extract(a.payload_json,'$.session.cwd')AND sess.started_at IS json_extract(a.payload_json,'$.session.startedAt')AND sess.ended_at IS json_extract(a.payload_json,'$.session.endedAt')))AND((json_type(a.payload_json,'$.run')='null' AND NOT EXISTS(SELECT 1 FROM memory_data_runs WHERE attempt_id=a.id))OR EXISTS(SELECT 1 FROM memory_data_runs l JOIN runs r ON r.id=l.run_id WHERE l.attempt_id=a.id AND r.capture_attempt_id=a.id AND l.run_json=json_extract(a.payload_json,'$.run')AND r.kind='capture' AND r.host=json_extract(a.payload_json,'$.machineId')AND r.started_at=json_extract(a.payload_json,'$.run.startedAt')AND r.finished_at=json_extract(a.payload_json,'$.run.finishedAt')AND r.status='ok' AND r.counts=json_extract(a.payload_json,'$.run.counts')AND json_extract(r.counts,'$.added')=json_array_length(a.payload_json,'$.facts')AND json_extract(r.counts,'$.superseded')=(SELECT count(*)FROM memory_data_supersedes WHERE attempt_id=a.id)AND json_extract(r.counts,'$.captured')=CASE WHEN json_type(a.payload_json,'$.session')='null' THEN 0 ELSE 1 END));

CREATE TRIGGER memory_legacy_deployment_completion_guard BEFORE INSERT ON memory_legacy_deployment_completions WHEN NOT EXISTS(SELECT 1 FROM memory_legacy_deployment_attempts a JOIN memory_legacy_deployments d ON d.id=a.id JOIN memory_legacy_deployment_audit audit ON audit.attempt_id=a.id AND audit.id=NEW.audit_id WHERE a.id=NEW.attempt_id AND a.request_hash=NEW.request_hash AND audit.request_hash=a.request_hash AND audit.outcome_json=NEW.outcome_json AND d.predecessor_id=json_extract(a.payload_json,'$.predecessorId') AND d.previous_pin_hash=json_extract(a.payload_json,'$.previousPinHash') AND d.pin_hash=json_extract(a.payload_json,'$.pinHash') AND d.review_hash=json_extract(a.payload_json,'$.reviewHash') AND d.evidence_json=json_extract(a.payload_json,'$.evidence') AND d.protocol_hash=json_extract(a.payload_json,'$.protocolHash') AND d.route_contract_hash=json_extract(a.payload_json,'$.routeContractHash') AND d.rollback=json_extract(a.payload_json,'$.rollback') AND d.source_hash=a.source_hash) BEGIN SELECT RAISE(ABORT,'deployment completion requires exact reviewed successor'); END;

INSERT OR IGNORE INTO schema_migrations(version,applied_at) VALUES(15,datetime('now'));
